// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame, ERC20Interface} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(address tokenOwner, uint256 tokens) public {
        // Admissible domain: recipient is a plain EOA distinct from the token,
        // the contract itself, and the owner/caller (the test contract).
        RecordingToken token = new RecordingToken();
        vm.assume(tokenOwner != address(token));
        vm.assume(tokenOwner != address(c));
        vm.assume(tokenOwner != address(this));
        vm.assume(tokenOwner.code.length == 0);

        // Rule: for any such recipient and any amount, the owner call succeeds —
        // the reference forwards the tokens to the tokenOwner argument, which the
        // token accepts; the mutant pays msg.sender (this contract, which has
        // code) and the token rejects it, so the call reverts.
        bool ok;
        try c.transferAnyERC20Token(address(token), tokenOwner, tokens) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract RecordingToken is ERC20Interface {
    address public lastRecipient;
    uint256 public lastAmount;

    function transfer(address to, uint256 tokens) override public returns (bool success) {
        // Reject payments to contracts (e.g. the owner/test contract itself);
        // accept payments to plain EOAs.
        require(to.code.length == 0, "contracts not accepted");
        lastRecipient = to;
        lastAmount = tokens;
        return true;
    }
}
